function startAt(p){if(!state.graph)return toast('3D 지도를 시작하지 못해 이동 기능을 사용할 수 없습니다.');const near=state.graph.nearest(geo(p.lon,p.lat),240);if(!near)return toast('출발점 근처의 보행 가능한 도로를 찾지 못했습니다.');stopRoute(false);player.pos=[...near.point];state.edge=near.edge;setMode('walk');closeDetail();$('#position-label').textContent=p.district+' · '+p.name;toast(`${p.name} 주변 도로에서 시작합니다. 실제 출입구·보행 가능 여부는 검증 전입니다.`);}
function walkTo(p){if(!state.graph)return toast('이동 기능은 3D 지도 초기화 후 사용할 수 있습니다.');let r=state.graph.route(player.pos,geo(p.lon,p.lat),240);if(!r.ok)return toast(r.error);closeDetail();beginRoute(r,p.name);if(r.gap>25)toast('장소 중심이 아닌 가까운 도로 지점까지만 이동합니다. 출입구는 별도 확인이 필요합니다.');}
function beginRoute(r,name){state.route=r;state.routeIndex=1;state.routeTravel=0;state.auto=true;player.pos=[...r.points[0]];state.renderer?.setRoute(r.points);$('#walk-progress').hidden=false;$('#route-name').textContent=name;setMode('walk');$('#nearby-prompt').hidden=true;}
function stopRoute(notify=true){state.auto=false;state.route=null;state.routeTravel=0;state.renderer?.setRoute([]);$('#walk-progress').hidden=true;if(notify)toast('자동 산책을 멈췄습니다. 직접 캐릭터를 움직일 수 있습니다.');}
function renderTours(){const host=$('#tour-list');host.replaceChildren();for(const t of tours){let el=document.createElement('article');el.className='tour-card';el.innerHTML=`<span class="eyebrow">${esc(t.eyebrow)}</span><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><ol>${t.stops.map(id=>`<li>${esc(places.find(p=>p.id===id)?.name||id)}</li>`).join('')}</ol><button>${icon('walk')}이 코스 미리 걷기 ${icon('arrow')}</button>`;el.querySelector('button').addEventListener('click',()=>walkItinerary(t.stops,t.name,true));host.append(el);}const p=document.createElement('p');p.className='saved-intro';p.textContent='테마는 서비스에서 구성한 예시이며 공식 성안올레 코스와 동일하지 않습니다. 가상 경로의 거리와 보행 가능 여부는 현장 검증 전입니다.';host.append(p);}
function walkItinerary(ids,name,teleport=false){if(!state.graph)return toast('3D 지도 초기화가 필요합니다.');if(!ids.length)return toast('먼저 장소를 여정에 담아 주세요.');let start=[...player.pos],points=[],distance=0;if(teleport){const first=places.find(p=>p.id===ids[0]);const n=state.graph.nearest(geo(first.lon,first.lat),240);if(!n)return toast('코스 출발 지점의 보행 도로를 찾지 못했습니다.');start=n.point;}for(const id of ids){let p=places.find(p=>p.id===id);if(!p)continue;const r=state.graph.route(start,geo(p.lon,p.lat),240);if(!r.ok)return toast(`${p.name}: ${r.error}`);points.push(...(points.length?r.points.slice(1):r.points));distance+=r.distance;start=r.points[r.points.length-1];}if(points.length<2||distance<1)return toast('이동할 경로가 거의 없습니다. 다른 장소를 추가해 주세요.');closeDetail();$('#sidebar').classList.remove('mobile-open');beginRoute({ok:true,points,distance,gap:0},name);toast('예시 코스를 가상으로 걷습니다. 실제 보도·횡단보도·경사·영업 여부는 별도 확인하세요.');}
function renderSaved(){const host=$('#saved-list');host.replaceChildren();let p=document.createElement('p');p.className='saved-intro';p.textContent='저장한 순서대로, 나만의 원도심 산책. 최대 8곳을 연결할 수 있으며 이 브라우저에만 보관됩니다.';host.append(p);if(!saved.length){host.innerHTML+=`<div class="empty">${icon('bookmark')}<strong>아직 비어 있는 여정</strong>장소 옆 책갈피를 눌러<br>가고 싶은 곳을 담아 주세요.</div>`;return;}saved.forEach((id,i)=>{const p=places.find(p=>p.id===id);if(!p)return;const row=document.createElement('div');row.className='saved-item';row.innerHTML=`<b>${i+1}</b><div><button class="place-title">${esc(p.name)}</button><small>${esc(p.district)} · ${esc(labels[p.category])}</small></div><button class="remove-saved" aria-label="${esc(p.name)} 여정에서 삭제">${icon('close')}</button>`;row.querySelector('.place-title').addEventListener('click',()=>selectPlace(id));row.querySelector('.remove-saved').addEventListener('click',()=>savePlace(id));host.append(row);});const actions=document.createElement('div');actions.className='saved-actions';actions.innerHTML=`<button class="primary full" id="walk-saved">${icon('walk')}담은 순서로 미리 걷기</button><button class="secondary full" id="export-itinerary">${icon('download')}여정 JSON 저장</button>`;host.append(actions);$('#walk-saved').addEventListener('click',()=>walkItinerary(saved,'나의 여정'));$('#export-itinerary').addEventListener('click',()=>downloadJSON({schemaVersion:1,type:'itinerary',createdAt:new Date().toISOString(),notice:'사전 체험용. 실제 길찾기 아님.',stops:saved.map(id=>places.find(p=>p.id===id))},'jeju-itinerary.json'));}
function switchTab(tab){state.tab=tab;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#explore-controls').hidden=tab!=='explore';$('#place-list').hidden=tab!=='explore';$('#tour-list').hidden=tab!=='tours';$('#saved-list').hidden=tab!=='saved';$('#panel-title').textContent={explore:'어디부터 걸어볼까요?',tours:'발길이 머무는 코스',saved:'나만의 제주 여정'}[tab];if(tab==='tours')renderTours();if(tab==='saved')renderSaved();if(innerWidth<=680)$('#sidebar').classList.add('mobile-open');}
function openHelp(){state.keys.clear();state.joystick=[0,0];$('#accuracy-message').textContent=map.mode==='osm'?'도로·건물 윤곽과 해안선은 OpenStreetMap 원본입니다. 대부분의 높이는 9m 가정값이며, 층수 제공 건물은 층당 3m로 환산했습니다. 사진 재질은 Poly Haven의 일반 표면 스캔으로 제주 현장사진이 아닙니다. 창문·옥상 장치·수목 크기·빛·차선 표현은 시각화입니다. 지형 고도·현장 보행 조건·출입구는 검증 전입니다.':'현재 묶음에는 실제 도로·건물 원본이 없습니다. 도로·해안·건물은 개략 배치와 절차적 생성으로 구성한 공간 초안입니다. 실제 거리·경관·행정경계를 재현했다고 해석하면 안 됩니다.';$('#technical-status').textContent=`MAP MODE: ${map.mode.toUpperCase()}\nSOURCE: ${map.source}\nCAPTURED: ${map.capturedAt||'원본 미수신'}\nNAVER API: ${state.naverConfigured?'서버 키 설정됨 · 조회별 확인 필요':'미설정 / 외부 지도 링크만 제공'}\nGEOMETRY: ${state.renderer?.buildCount||0} 건물 / ${map.roads.length} 도로 객체\nCURATED POI: ${base.length} · COORDINATES: 검증 전\nCUSTOM POI: ${custom.length} · BROWSER ONLY\nBOUNDARY: 사각 표시범위 · 행정경계 검증 전`;$('#help-dialog').showModal();}
function downloadJSON(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
