$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error('JSON 파일은 2MB 이하만 가져올 수 있습니다.');const next=validatePlaces(JSON.parse(await file.text()));if(next.some(p=>base.some(b=>b.id===p.id)))throw Error('기본 장소와 ID가 겹칩니다. 사용자 장소 ID를 별도로 지정해 주세요.');let merged=new Map(custom.map(p=>[p.id,p]));for(const p of next)merged.set(p.id,p);if(merged.size>1000)throw Error('전체 사용자 장소는 최대 1,000개입니다.');custom=[...merged.values()];places=[...base,...custom];setLocal('places',custom);refreshPins();renderList();updateSavedCount();toast(`${next.length}개 장소를 이 브라우저로 가져왔습니다.`);}catch(err){toast('가져오기 실패: '+err.message);}e.target.value='';});
