const controls=new Set(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','ShiftLeft','ShiftRight']);
addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select')||$('dialog[open]'))return;if(e.code==='Escape'){closeDetail();$('#sidebar').classList.remove('mobile-open');state.keys.clear();return;}if(e.code==='Slash'){e.preventDefault();switchTab('explore');$('#search').focus();return;}if(e.code==='KeyE'){const n=nearestPlace();if(n&&n.d<70)selectPlace(n.p.id);return;}if(controls.has(e.code)){e.preventDefault();state.keys.add(e.code);if(state.auto)stopRoute(false);}});addEventListener('keyup',e=>state.keys.delete(e.code));addEventListener('blur',()=>{state.keys.clear();state.joystick=[0,0];});document.addEventListener('visibilitychange',()=>{state.keys.clear();state.joystick=[0,0];state.lastFrame=performance.now();});
let drag=null,pointers=new Map(),oldPinch=null;const canvas=$('#world');
canvas.addEventListener('pointerdown',e=>{if(e.button>1)return;canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);drag={x:e.clientX,y:e.clientY,button:e.button};if(pointers.size===2){const p=[...pointers.values()];oldPinch=dist(p[0],p[1]);}});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!state.renderer)return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){const p=[...pointers.values()],d=dist(p[0],p[1]);if(oldPinch)state.renderer.distance=clamp(state.renderer.distance*oldPinch/d,10,40000);oldPinch=d;return;}if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(e.shiftKey||drag.button===1){const scale=state.renderer.distance/Math.max(400,canvas.clientHeight),y=state.renderer.yaw;state.renderer.target[0]-=(dx*Math.cos(y)+dy*Math.sin(y))*scale;state.renderer.target[2]-=(-dx*Math.sin(y)+dy*Math.cos(y))*scale;}else{state.renderer.yaw-=dx*.006;state.renderer.pitch=clamp(state.renderer.pitch+dy*.004,.24,1.52);}drag.x=e.clientX;drag.y=e.clientY;});
function endDrag(e){pointers.delete(e.pointerId);if(!pointers.size)drag=null;oldPinch=null;if(pointers.size===1){const p=[...pointers.values()][0];drag={x:p[0],y:p[1],button:0};}}canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);canvas.addEventListener('lostpointercapture',endDrag);canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('wheel',e=>{e.preventDefault();if(state.renderer)state.renderer.distance=clamp(state.renderer.distance*Math.exp(e.deltaY*.001),10,40000);},{passive:false});
let joyId=null;const joy=$('#joystick');function joyUpdate(e){const r=joy.getBoundingClientRect();let x=(e.clientX-r.left-r.width/2)/29,y=(e.clientY-r.top-r.height/2)/29,l=Math.hypot(x,y);if(l>1){x/=l;y/=l;}state.joystick=[x,y];joy.firstElementChild.style.transform=`translate(${x*23}px,${y*23}px)`;}
joy.addEventListener('pointerdown',e=>{e.preventDefault();joyId=e.pointerId;joy.setPointerCapture(joyId);if(state.auto)stopRoute(false);joyUpdate(e);});joy.addEventListener('pointermove',e=>{if(joyId===e.pointerId)joyUpdate(e);});function joyEnd(){joyId=null;state.joystick=[0,0];joy.firstElementChild.style.transform='';}joy.addEventListener('pointerup',joyEnd);joy.addEventListener('pointercancel',joyEnd);joy.addEventListener('lostpointercapture',joyEnd);
function nearestPlace(){let best=null;for(const p of places){let d=dist(player.pos,geo(p.lon,p.lat));if(!best||d<best.d)best={p,d};}return best;}
$('#nearby-prompt button').addEventListener('click',()=>{const n=nearestPlace();if(n)selectPlace(n.p.id);});
function updateMotion(dt){if(!state.graph||$('dialog[open]'))return false;let moving=false;if(state.auto&&state.route){let remain=1.35*state.speed*dt;while(remain>0&&state.routeIndex<state.route.points.length){let target=state.route.points[state.routeIndex],len=dist(player.pos,target);if(len<.01){state.routeIndex++;continue;}let step=Math.min(remain,len),dx=(target[0]-player.pos[0])/len,dz=(target[1]-player.pos[1])/len;player.pos[0]+=dx*step;player.pos[1]+=dz*step;player.heading=Math.atan2(dx,dz);state.totalWalk+=step;state.routeTravel+=step;remain-=step;moving=true;if(step>=len-.001)state.routeIndex++;}if(state.routeIndex>=state.route.points.length){state.auto=false;state.edge=state.graph.nearest(player.pos,30)?.edge;$('#walk-progress').hidden=true;toast('가상 산책 지점에 도착했습니다. 실제 출입구와 운영 여부는 네이버 지도에서 확인해 주세요.');}else{$('#route-remain').textContent=displayDistance(Math.max(0,state.route.distance-state.routeTravel))+' 남음 · '+state.speed+'×';$('#route-bar').style.width=clamp(state.routeTravel/state.route.distance*100,0,100)+'%';}}
 else{let right=(state.keys.has('KeyD')||state.keys.has('ArrowRight')?1:0)-(state.keys.has('KeyA')||state.keys.has('ArrowLeft')?1:0)+state.joystick[0],forward=(state.keys.has('KeyW')||state.keys.has('ArrowUp')?1:0)-(state.keys.has('KeyS')||state.keys.has('ArrowDown')?1:0)-state.joystick[1];let mag=Math.hypot(right,forward);if(mag>.03){right/=Math.max(1,mag);forward/=Math.max(1,mag);let yaw=state.renderer?.yaw||0,dx=right*Math.cos(yaw)-forward*Math.sin(yaw),dz=-right*Math.sin(yaw)-forward*Math.cos(yaw),speed=state.keys.has('ShiftLeft')||state.keys.has('ShiftRight')?4.2:1.4;let step=speed*dt,desired=[player.pos[0]+dx*step,player.pos[1]+dz*step];let hit=state.graph.constrain(player.pos,desired,state.edge);if(!hit){const near=state.graph.nearest(desired,14);if(near&&(!state.edge||near.edge.id===state.edge.id||[state.edge.ai,state.edge.bi].includes(near.edge.ai)||[state.edge.ai,state.edge.bi].includes(near.edge.bi))){const proj=state.graph.constrain(player.pos,near.point,state.edge);if(proj&&dist(player.pos,proj.point)<step*2+.08)hit=proj;}}if(hit){state.totalWalk+=dist(player.pos,hit.point);player.pos=hit.point;state.edge=hit.edge;player.heading=Math.atan2(dx,dz);moving=true;}}}
 if(moving){state.phase+=dt;const nearest=nearestPlace();if(nearest&&nearest.d<500)$('#position-label').textContent=nearest.p.district+' · '+nearest.p.name+' 주변';}if(state.mode==='walk'&&state.renderer){if(state.auto&&!drag){const desired=player.heading+Math.PI,delta=Math.atan2(Math.sin(desired-state.renderer.yaw),Math.cos(desired-state.renderer.yaw));state.renderer.yaw+=delta*Math.min(1,dt*3);}state.renderer.target[0]=player.pos[0];state.renderer.target[2]=player.pos[1];state.renderer.target[1]=1.1;}$('#walk-distance').textContent=(state.totalWalk/1000).toFixed(2);return moving;}
function positionPins(){const r=state.renderer;if(!r)return;const max=innerWidth<680?8:16;let allowed=places.filter(p=>matches(p)||p.id===state.selected).map(p=>({p,d:dist([r.target[0],r.target[2]],geo(p.lon,p.lat))})).sort((a,b)=>a.p.id===state.selected?-1:b.p.id===state.selected?1:r.distance>5000&&a.p.category==='transport'?-1:r.distance>5000&&b.p.category==='transport'?1:a.d-b.d);let visible=0,rects=[];for(const el of pinElements.values())el.style.display='none';for(const{p,d}of allowed){if(visible>=max&&p.id!==state.selected)continue;const q=geo(p.lon,p.lat),pos=r.project(q[0],p.kind==='hotel'?51:20,q[1]);if(!pos?.visible||pos.z>1||pos.x<18||pos.x>r.width-20||pos.y<14||pos.y>r.height-115)continue;if(state.mode==='walk'&&d>350&&p.id!==state.selected)continue;let el=pinElements.get(p.id);const small=r.distance>5000,w=small?(p.category==='transport'?170:35):Math.min(190,p.name.length*11+40),h=small?32:38,rect=[pos.x-w/2,pos.y-h,pos.x+w/2,pos.y];if(rects.some(a=>rect[0]<a[2]+5&&rect[2]>a[0]-5&&rect[1]<a[3]+5&&rect[3]>a[1]-5)&&p.id!==state.selected)continue;if(state.mode==='overview'&&pos.x<300&&pos.y<285&&p.id!==state.selected)continue;rects.push(rect);el.classList.toggle('small',small);el.style.display='flex';el.style.left=pos.x+'px';el.style.top=pos.y+'px';visible++;}const size=r.distance>130?Math.min(4,r.distance/130):1,q=r.project(player.pos[0],3.1*size,player.pos[1]);playerLabel.style.display=q?.visible?'block':'none';if(q){playerLabel.style.left=q.x+'px';playerLabel.style.top=q.y+'px';playerLabel.textContent=player.name;}$('#compass-arrow').style.transform=`rotate(${-r.yaw}rad)`;}
function drawMinimap(){const canvas=$('#minimap'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;const min=geo(C.bounds[0],C.bounds[3]),max=geo(C.bounds[2],C.bounds[1]);const scale=Math.min((w-16)/(max[0]-min[0]),(h-14)/(max[1]-min[1]));const to=p=>[8+(p[0]-min[0])*scale,7+(p[1]-min[1])*scale];ctx.fillStyle='#22474c';ctx.fillRect(0,0,w,h);ctx.fillStyle='#577567';const coast=(map.coast||[]).map(c=>to(geo(...c)));if(coast.length){ctx.beginPath();coast.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.lineTo(...to([max[0],max[1]]));ctx.lineTo(...to([min[0],max[1]]));ctx.closePath();ctx.fill();}else{ctx.fillStyle='#45675e';ctx.fillRect(0,40,w,h);}ctx.strokeStyle='#92ab8f';ctx.lineWidth=.6;ctx.beginPath();for(const r of map.roads){if(!r.coords?.length)continue;const first=to(geo(...r.coords[0]));ctx.moveTo(...first);for(const c of r.coords.slice(1))ctx.lineTo(...to(geo(...c)));}ctx.stroke();if(state.route){ctx.strokeStyle='#d7f58a';ctx.lineWidth=1.5;ctx.beginPath();state.route.points.forEach((p,i)=>i?ctx.lineTo(...to(p)):ctx.moveTo(...to(p)));ctx.stroke();}for(const p of places){if(!['attraction','transport'].includes(p.category))continue;let q=to(geo(p.lon,p.lat));ctx.fillStyle=p.category==='transport'?'#ded9e4':'#cee3b0';ctx.beginPath();ctx.arc(...q,p.category==='transport'?2.1:1.15,0,Math.PI*2);ctx.fill();}let p=to(player.pos);ctx.fillStyle='#f4b278';ctx.strokeStyle='#173c31';ctx.lineWidth=1.3;ctx.beginPath();ctx.arc(...p,3,0,6.3);ctx.fill();ctx.stroke();ctx.font='9px sans-serif';ctx.fillStyle='#cee5cb';ctx.fillText('N',w-16,14);ctx.font='8px sans-serif';let air=to(geo(126.4936,33.5062));ctx.fillText('CJU',air[0]-7,air[1]-6);}
function loop(now){if(state.destroyed)return;requestAnimationFrame(loop);if(document.hidden){state.lastFrame=now;return;}if(!state.lastFrame){state.lastFrame=now;return;}const dt=Math.min((now-state.lastFrame)/1000,.08);if(dt<1/35)return;state.lastFrame=now;let moving=updateMotion(dt);state.renderer?.draw(player,state.phase,moving);positionPins();if(state.metrics.frames++%6===0){drawMinimap();const n=nearestPlace();const show=state.mode==='walk'&&!state.auto&&!state.selected&&!$('dialog[open]')&&n?.d<65;$('#nearby-prompt').hidden=!show;if(show)$('#nearby-prompt>span').textContent=n.p.name;}}
async function serverStatus(){state.naverConfigured=false;}
function init(){try{state.graph=new C.RoadGraph(map.roads,{splitCrossings:map.mode==='schematic'});let near=state.graph.nearest(player.pos,250);if(near){player.pos=near.point;state.edge=near.edge;}state.renderer=new JejuRender.WorldRenderer(canvas,map,places,state.graph);state.renderer.focus(geo(126.5256,33.5132),innerWidth<680?980:850);state.renderer.yaw=.32;state.renderer.pitch=.65;state.renderer.onLost=()=>{toast('그래픽 연결이 중단되었습니다. 복구를 기다리거나 새로고침해 주세요.');};if(map.mode==='osm'){$('#data-status span').textContent='실제 윤곽 · 외관 연출';$('#data-status i').style.backgroundColor='#d7f58a';$('#data-footer').textContent='OSM 윤곽 · 외관·높이·보행 조건 미검증';$('#osm-credit').hidden=false;$('.minimap-foot span:last-child').textContent='OSM';}else{$('#data-footer').textContent='공간·위치 초안 · 실제 길찾기 아님';}state.renderer.draw(player,0,false);drawMinimap();$('#loading').hidden=true;requestAnimationFrame(loop);}catch(e){$('#loading').hidden=true;$('#fatal').hidden=false;$('#fatal p').textContent=e.message||'3D 초기화 오류';console.error('3D initialization failed',e);}}

$('#export-map').addEventListener('click',()=>downloadJSON(map,map.mode==='osm'?'map-osm.json':'map-seed.export.json'));
let osmLoading=false,osmLastAttempt=0;
$('#load-osm').addEventListener('click',async()=>{
 const btn=$('#load-osm'),msg=$('#osm-load-message');if(osmLoading)return;
 if(Date.now()-osmLastAttempt<60000){msg.textContent='원본 서버 보호를 위해 1분 후 다시 시도해 주세요.';return;}
 if(!state.renderer){msg.textContent='3D 지도가 실행된 뒤 사용할 수 있습니다.';return;}
 osmLastAttempt=Date.now();osmLoading=true;btn.disabled=true;
 try{
  const raw=await JejuOSM.downloadOverpass({signal:AbortSignal.timeout(210000),onProgress:t=>msg.textContent=t});
  const loaded=JejuOSM.convertOverpass(raw,{fallbackCoast:map.coast});
  const graph=new C.RoadGraph(loaded.roads);const spawn=graph.nearest(player.pos,500);
  if(!spawn)throw Error('출발점 주변에 공개 보행 도로가 없습니다.');
  const previousMap=map,previousGraph=state.graph;
  state.renderer.map=loaded;state.renderer.graph=graph;
  try{state.renderer.buildWorld();}catch(error){state.renderer.map=previousMap;state.renderer.graph=previousGraph;state.renderer.buildWorld();throw error;}
  stopRoute(false);map=loaded;state.graph=graph;state.edge=spawn.edge;player.pos=spawn.point;
  state.renderer.focus(player.pos,760);setMode('overview');
  $('#data-status span').textContent='OSM 적용';$('#data-status i').style.backgroundColor='#d7f58a';$('#data-footer').textContent='OSM 도로·건물 · 외관·장소 검증 전';$('#osm-credit').hidden=false;$('.minimap-foot span:last-child').textContent='OSM';
  msg.textContent=`원본 적용: 도로 ${loaded.roads.length.toLocaleString()}개, 건물 ${loaded.buildings.length.toLocaleString()}개. 이 탭에서만 유지됩니다. `+loaded.notice;
  btn.textContent='OSM 원본 적용됨';toast('실제 도로·건물 원본을 적용했습니다. 장소 좌표와 외관은 별도 확인이 필요합니다.');
 }catch(e){msg.textContent='원본 수신 실패: '+e.message+' 기존 지도 상태를 유지합니다.';btn.disabled=false;}finally{osmLoading=false;}
});

$('.brand').addEventListener('click',e=>{e.preventDefault();state.category='all';$('#search').value='';switchTab('explore');fitAll();});
refreshPins();renderList();renderTours();updateSavedCount();serverStatus();setTimeout(()=>{init();const b=document.querySelector('#load-osm');b.disabled=true;b.textContent='실제 OSM 데이터 적용됨';document.querySelector('#osm-load-message').textContent='수신 '+map.capturedAt+' · 건물 '+map.buildings.length.toLocaleString()+'개 / 도로 '+map.roads.length.toLocaleString()+'개';},60);
